"""The dispatcher every harness drives: payload id -> build, encode, decode, per arm.

Generated rather than reflected. Reflection would put a `Method.invoke` on the measured
path, and the whole slice is a measurement of a few tens of nanoseconds per crossing.
"""
import java_names as N

HEAD = ("// @generated by ffi/poc/java/gen/generate.py from ffi/schema/shapes.json."
        " Do not edit.\n")


def _payload_ids(ir):
    out = []
    for pid, spec in ir.payloads.items():
        if spec["root"] not in ir.messages:
            continue
        out.append((pid, spec))
    return out


def emit(ir, ns=N.PKG):
    o = [HEAD, "package %s;" % ns, "", "import ak.Dec;", "import ak.Enc;", "",
         "/** Payload id -> build, encode, decode, for every arm. One switch, generated,",
         " *  so the measured path carries no reflection. */",
         "public final class Arms {",
         "  private Arms() {}",
         ""]

    ids = [pid for pid, _ in _payload_ids(ir)]
    o.append("  public static final String[] IDS = {%s};"
             % ", ".join('"%s"' % p for p in ids))
    o.append("")
    o.append("  /** P7.1 interleaves two repeated fields of one type, which no canonical")
    o.append("   *  writer can produce (design/SHAPES.md). It is validated by DECODE and")
    o.append("   *  by re-encoding to a permutation of the same triples, never by")
    o.append("   *  reproducing its bytes. */")
    o.append("  public static boolean encodable(String id) {")
    noenc = [pid for pid, spec in _payload_ids(ir) if spec.get("interleaved")]
    o.append("    return !(%s);" % " || ".join('id.equals("%s")' % p for p in noenc)
             if noenc else "    return true;")
    o.append("  }")
    o.append("")
    o.append("  public static String root(String id) {")
    o.append("    switch (id) {")
    for pid, spec in _payload_ids(ir):
        o.append('      case "%s": return "%s";' % (pid, spec["root"]))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")

    # ---- build
    o.append("")
    o.append("  public static Object build(String id, int cs) {")
    o.append("    switch (id) {")
    for pid, spec in _payload_ids(ir):
        if spec.get("interleaved"):
            o.append('      case "%s": return null;   // decode only' % pid)
        else:
            o.append('      case "%s": return Build.payload%s(cs);'
                     % (pid, pid.replace(".", "_")))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")

    # ---- arm R
    o.append("")
    o.append("  /** Arm R: the generated pure-Java codec (README R3's no-boundary")
    o.append("   *  control, and section 13 outcome 2's architecture). */")
    o.append("  public static void encodeR(String id, Object o, Enc e) {")
    o.append("    switch (id) {")
    for pid, spec in _payload_ids(ir):
        root = spec["root"]
        o.append('      case "%s": Codec.encodeInto%s(e, (%s) o); break;' % (pid, root, root))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")
    o.append("")
    o.append("  public static Object decodeR(String id, Dec d, byte[] buf, int off, int len) {")
    o.append("    switch (id) {")
    for pid, spec in _payload_ids(ir):
        root = spec["root"]
        o.append('      case "%s": return Codec.decode%s(d, buf, off, len);' % (pid, root))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")
    o.append("}")
    o.append("")
    return "\n".join(o)
